import express from "express";
import path from "path";
import { createServer as createViteServer } from "vite";
import { createServer } from "http";
import { WebSocketServer, WebSocket } from "ws";

async function startServer() {
  const app = express();
  const PORT = 3000;
  const httpServer = createServer(app);

  app.get("/api/health", (req, res) => {
    res.json({ status: "ok" });
  });

  const wss = new WebSocketServer({ server: httpServer });

  interface PlayerState {
     ws: any;
     name: string;
     queueId: string;
  }

  let waitingPlayer: PlayerState | null = null;

  wss.on("connection", (ws) => {
    let opponentSocket: any = null;
    let isP1 = false;

    ws.on("message", (message) => {
      try {
        const data = JSON.parse(message.toString());

        if (data.type === "join_queue") {
          if (waitingPlayer && waitingPlayer.ws !== ws) {
            // Match found!
            opponentSocket = waitingPlayer.ws;
            waitingPlayer.ws.opponentSocket = ws; // Attach reverse directly
            isP1 = false;
            
            // Assign roles
            ws.send(JSON.stringify({
              type: "match_found",
              role: "p2",
              opponentName: waitingPlayer.name
            }));
            
            waitingPlayer.ws.send(JSON.stringify({
              type: "match_found",
              role: "p1",
              opponentName: data.name || "Player 2"
            }));
            
            waitingPlayer = null;
          } else {
            waitingPlayer = { ws, name: data.name || "Player 1", queueId: Date.now().toString() };
          }
        } 
        else if (data.type === "action") {
          // Relay action to opponent
          // We fetch opponentSocket from the ws object if it was stored there
          const targetWs = (ws as any).opponentSocket || opponentSocket;
          if (targetWs && targetWs.readyState === WebSocket.OPEN) {
            targetWs.send(JSON.stringify(data));
          }
        }
      } catch (err) {
        console.error(err);
      }
    });

    ws.on("close", () => {
      if (waitingPlayer && waitingPlayer.ws === ws) {
        waitingPlayer = null;
      }
      const targetWs = (ws as any).opponentSocket || opponentSocket;
      if (targetWs && targetWs.readyState === WebSocket.OPEN) {
        targetWs.send(JSON.stringify({ type: "opponent_disconnected" }));
      }
    });
  });

  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  httpServer.listen(PORT, "0.0.0.0", () => {
    console.log(`Server listening on address http://localhost:${PORT}`);
  });
}

startServer();
